const crypto = require('crypto');
const input = $input.first().json;
const hash = crypto
  .createHash('sha256')
  .update(input.question)
  .digest('hex');
return [{ json: { ...input, question_hash: hash } }];

// Supabase returns an array directly as the response body
let chunks = $input.first().json;
if (!Array.isArray(chunks)) {
  chunks = chunks ? [chunks] : [];
}

// Build RAG context from retrieved chunks
const contextText = chunks.length > 0
  ? chunks.map((c, i) => `[Source ${i + 1}: ${c.doc_name}]\n${c.content}`).join('\n\n---\n\n')
  : 'No relevant documents found in the knowledge base.';

// Build sources list for the final response
const sources = chunks.map(c => ({
  doc_name: c.doc_name,
  relevance_score: Math.round((c.similarity || 0) * 100) / 100
}));

// Carry forward all upstream fields
const prev = $('Generate Hash').first().json;

return [{
  json: {
    ...prev,
    context: contextText,
    sources: sources
  }
}];

