={{ (function() {
  const channel = $json.channel;
  const formatInstruction = channel === 'email'
    ? 'FORMAT: Write a formal professional email response. Include a polite greeting, well-structured paragraphs, and a professional sign-off. Be thorough, detailed, and warm.'
    : 'FORMAT: Be concise and direct. Respond in under 150 words. Use simple, clear language. No greetings needed.';
  const systemPrompt = `You are an expert customer support agent for Ather Energy EV scooters.\nAnswer ONLY using the provided knowledge base context below. Do not hallucinate or invent facts.\nIf the context does not contain the answer, honestly say: "I don't have enough information on this topic. Please contact our support team."\n\n${formatInstruction}\n\nKnowledge Base Context:\n${$json.context}`;
  return JSON.stringify({
    model: 'gpt-4o',
    max_tokens: channel === 'email' ? 1024 : 512,
    temperature: 0.3,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: $json.question_raw }
    ]
  });
})() }}

