={{ (function() {
  const prompt = `You are a strict QA evaluator for an AI customer support system.

Evaluate whether the AI answer correctly and accurately addresses the customer question.
Check for: hallucinations, incorrect facts, missing critical information, or off-topic responses.

Customer Question:
${$json.question_raw}

AI Answer:
${$json.l1_answer}

Knowledge Base Context Used:
${$json.context}

Respond ONLY with valid JSON — no markdown, no explanation, nothing else:
{"score": <integer 0-10>, "label": "<Excellent|Good|Acceptable|Poor>", "rationale": "<one concise sentence>"}

Scoring Guide:
- 9-10 = Excellent: Fully accurate, complete, well-grounded in context
- 7-8  = Good: Accurate with minor omissions
- 5-6  = Acceptable: Mostly correct but noticeable gaps or mild issues
- 0-4  = Poor: Inaccurate, hallucinated facts, off-topic, or harmful`;
  return JSON.stringify({
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: { temperature: 0.1, maxOutputTokens: 256 }
  });
})() }}

