const geminiResponse = $input.first().json;
const rawText = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';

let rating;
try {
  // Strip markdown code fences if Gemini wraps output
  const cleaned = rawText
    .replace(/^```json\s*/i, '')
    .replace(/```\s*$/, '')
    .trim();
  rating = JSON.parse(cleaned);
  // Validate label is one of the expected values
  if (!['Excellent', 'Good', 'Acceptable', 'Poor'].includes(rating.label)) {
    rating.label = 'Acceptable';
  }
  rating.score = Math.max(0, Math.min(10, Number(rating.score) || 5));
} catch (e) {
  // Safe fallback — do not block on parse failure
  rating = {
    score: 5,
    label: 'Acceptable',
    rationale: 'L2 parse error — defaulting to Acceptable. Raw: ' + rawText.slice(0, 100)
  };
}

const prev = $('Extract L1 Answer').first().json;

return [{
  json: {
    ...prev,
    accuracy_score: rating.score,
    accuracy_label: rating.label,
    accuracy_rationale: rating.rationale,
    blocked: rating.label === 'Poor'
  }
}];

const now = new Date();
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, ''); // e.g. 20260308
const rand = String(Math.floor(Math.random() * 90000) + 10000);  // 5-digit
const ticketId = `SR-${dateStr}-${rand}`;

return [{ json: { ...$input.first().json, ticket_id: ticketId } }];
